const C = { ink: '#263D35', green: '#32644D', muted: '#7C867B', cream: '#F6F6F0', line: '#E6E8DF', soft: '#EAF0E4', orange: '#BF704D' };
type IconName = React.ComponentProps<typeof Ionicons>['name'];
type Tab = '行程' | '美食' | '記帳' | '相簿' | '聊天';
type Sheet = 'create' | 'event' | 'expense' | 'place' | 'settle' | 'share' | 'call' | 'help' | 'foodSearch' | null;
const tabs: { name: Tab; icon: IconName }[] = [{ name: '行程', icon: 'map-outline' }, { name: '美食', icon: 'restaurant-outline' }, { name: '記帳', icon: 'wallet-outline' }, { name: '相簿', icon: 'images-outline' }, { name: '聊天', icon: 'chatbubbles-outline' }];
const money = (n: number) => `¥ ${n.toLocaleString('en-US')}`;
const shortDate = (date: string) => `${Number(date.slice(5, 7))}/${Number(date.slice(8))}`;
const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
function Icon({ name, size = 21, color = C.ink }: { name: IconName; size?: number; color?: string }) { return <Ionicons name={name} size={size} color={color} />; }
function Btn({ title, onPress, icon, secondary = false, small = false, disabled = false }: { title: string; onPress: () => void; icon?: IconName; secondary?: boolean; small?: boolean; disabled?: boolean }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={title} disabled={disabled} onPress={onPress} style={({ pressed }) => [s.button, secondary && s.secondary, small && { paddingHorizontal: 14, minHeight: 42 }, (pressed || disabled) && { opacity: .6 }]}>{icon && <Icon name={icon} size={small ? 17 : 19} color={secondary ? C.green : 'white'} />}<Text style={[s.buttonText, secondary && { color: C.green }]}>{title}</Text></Pressable>;
}
function Chip({ children, active, onPress }: { children: React.ReactNode; active?: boolean; onPress?: () => void }) {
  return <Pressable accessibilityRole={onPress ? 'button' : undefined} onPress={onPress} style={[s.chip, active && { backgroundColor: C.green, borderColor: C.green }]}><Text style={[s.chipText, active && { color: 'white' }]}>{children}</Text></Pressable>;
}
function Avatar({ name, color, size = 32 }: { name: string; color: string; size?: number }) { return <View style={[s.avatar, { backgroundColor: color, width: size, height: size, borderRadius: size / 2 }]}><Text style={{ color: C.ink, fontSize: size * .36, fontWeight: '600' }}>{name.slice(0, 1)}</Text></View>; }
function Field({ label, value, onChangeText, placeholder, numeric, multiline }: { label: string; value: string; onChangeText: (v: string) => void; placeholder?: string; numeric?: boolean; multiline?: boolean }) {
  return <View style={{ gap: 8 }}><Text style={s.label}>{label}</Text><TextInput accessibilityLabel={label} value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#A0A69B" keyboardType={numeric ? 'numeric' : 'default'} multiline={multiline} style={[s.input, multiline && { height: 90, textAlignVertical: 'top' }]} /></View>;
}
function Photo({ uri, style }: { uri: string; style?: any }) {
  const [failed, setFailed] = useState(false);
  return <View style={[{ backgroundColor: '#E3E6DA', overflow: 'hidden' }, style]}>{failed ? <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', gap: 8 }}><Icon name="image-outline" color={C.muted} /><Text style={s.micro}>示意照片暫時無法載入</Text></View> : <Image source={{ uri }} style={{ width: '100%', height: '100%' }} onError={() => setFailed(true)} />}</View>;
}
const STORAGE = '@travel-journal/prototype-v1';
